import{_ as r,y as n,a,o as i,a2 as e,D as s}from"./chunks/framework.DCcmcJcL.js";const f=JSON.parse('{"title":"Command Palette","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/command-palette.md","filePath":"getting-started/command-palette.md","lastUpdated":1789441803000}'),g={name:"getting-started/command-palette.md"};function d(h,t,l,p,u,c){const o=n("ImagePopup");return i(),a("div",null,[t[0]||(t[0]=e('<h1 id="command-palette" tabindex="-1">Command Palette <a class="header-anchor" href="#command-palette" aria-label="Permalink to &quot;Command Palette&quot;">​</a></h1><p>The command palette is a search box that opens over any admin page. Type a few letters of what you are looking for and it lists the matching menu pages, configuration settings, actions and records, so you can reach any part of the admin panel without clicking through the sidebar.</p><p>It is available from Bagisto 2.5.</p><h2 id="opening-and-closing" tabindex="-1">Opening and closing <a class="header-anchor" href="#opening-and-closing" aria-label="Permalink to &quot;Opening and closing&quot;">​</a></h2><p>Press <strong>Ctrl + K</strong> (<strong>⌘ K</strong> on a Mac) on any admin page. The palette opens with the cursor in its search field.</p>',5)),s(o,{src:"/images/getting-started/command-palette.png",alt:"Command palette open with the Quick Access list"}),t[1]||(t[1]=e('<ul><li><strong>↑</strong> and <strong>↓</strong> move the highlight, and <strong>Enter</strong> opens the highlighted row.</li><li><strong>←</strong>, <strong>Backspace</strong> or <strong>Delete</strong> in an empty search field steps back out of a group you opened.</li><li><strong>Esc</strong>, the <strong>ESC</strong> badge, a click outside the box, or the shortcut again closes it.</li></ul><p>The search box in the header shows <strong>Ctrl K</strong> as a hint. Typed into directly, that box searches only products, orders, categories and customers. See <a href="./admin-panel.html#the-header">Admin Panel</a>.</p><h2 id="what-it-finds" tabindex="-1">What it finds <a class="header-anchor" href="#what-it-finds" aria-label="Permalink to &quot;What it finds&quot;">​</a></h2><p>Before you type, the palette shows <strong>Quick Access</strong>: every main menu item you can open, from <strong>Dashboard</strong> to <strong>Configure</strong>.</p><p>As you type, the results are grouped:</p><ul><li><strong>Pages</strong>: screens in the admin menu, each with its place in the menu, such as <strong>Tax Rates</strong> under <strong>Settings › Taxes</strong>. Common synonyms are understood, so &quot;vat&quot; finds <strong>Taxes</strong> under <strong>Settings</strong> and &quot;staff&quot; finds <strong>Users</strong>.</li><li><strong>Actions</strong>: things you start rather than places you go, such as <strong>Create Category</strong>, <strong>Create Attribute</strong> and <strong>Create CMS Page</strong>.</li><li><strong>Configuration</strong>: every screen, group and single setting under <strong>Configure</strong>, such as <strong>Apply Tax On</strong> under <strong>Configuration › Sales › Taxes › Calculation Settings</strong>.</li><li><strong>Products</strong>, <strong>Orders</strong>, <strong>Categories</strong> and <strong>Customers</strong>: records, once you have typed at least two characters. Each group shows up to five matches, and picking one opens it.</li></ul><p>If nothing matches, <em>No results found</em> appears.</p>',7)),s(o,{src:"/images/getting-started/command-palette-search.png",alt:"Command palette results for tax, grouped into Pages and Configuration"}),t[2]||(t[2]=e('<table tabindex="0"><thead><tr><th>Record</th><th>Found by</th></tr></thead><tbody><tr><td>Products</td><td>Name</td></tr><tr><td>Orders</td><td>The full order number, the order status, or part of the customer&#39;s email address, first name or last name</td></tr><tr><td>Categories</td><td>Part of the name</td></tr><tr><td>Customers</td><td>Part of the email address, first name or last name</td></tr></tbody></table><p>A search for a customer&#39;s full name, such as &quot;Mia Patel&quot;, finds nothing. Search for the first name, last name or email address instead.</p><p>You only see what your role is allowed to open. An admin without permission to manage customers, for example, sees no customer pages, actions or records, and an admin without the <strong>Configure</strong> permission sees no configuration results.</p><h2 id="browsing-a-group" tabindex="-1">Browsing a group <a class="header-anchor" href="#browsing-a-group" aria-label="Permalink to &quot;Browsing a group&quot;">​</a></h2><p>A row with an arrow at its end is a group. Opening it, with <strong>Enter</strong> or a click, shows the items underneath it and changes the search field to search that group only. The path you took is shown above the results: click <strong>Back</strong> or any step of the path to return to it.</p><p>This is the quickest way to browse a large list, such as every configuration screen under <strong>Sales</strong>, without knowing the exact name.</p><p>Some menu items open as a group rather than as their list page: <strong>Products</strong>, <strong>Orders</strong>, <strong>Categories</strong>, <strong>Customers</strong>, <strong>Attributes</strong>, <strong>CMS</strong>, <strong>Users</strong> and <strong>Imports</strong>. To open one of those lists, use the sidebar.</p><p>The <strong>Products</strong>, <strong>Orders</strong>, <strong>Categories</strong> and <strong>Customers</strong> groups have an <strong>All</strong> row, such as <strong>All Products</strong>. It shows <em>Type to search</em>: type part of a name, email or order number to list the matching records. Pick a record to choose what to do with it, such as <strong>Edit</strong> or <strong>View</strong>.</p><p>Each time you open the palette, it starts again at the top level.</p>',9))])}const _=r(g,[["render",d]]);export{f as __pageData,_ as default};
